//! The product compaction strategy: summarizes the history before the cut
//! with the request's own model (ContextCompaction §5.2).
const SYSTEM: &str = "You summarize a coding session so that it can continue without its earlier messages.";

impl CompactionStrategy for SummaryStrategy {
    fn name(&self) -> &str {
        "summary"
    }
    fn compact(&self, input: CompactionInput, cancel: CancellationToken) -> HostFuture<'_, StrategyOutcome> {
        Box::pin(async move {
            let Some(cut) = input.cut().cloned() else {
                return Ok(StrategyOutcome::Skipped { reason: "nothing_to_compact".into(), diagnostics: diagnostics(0, 0, 0., 0, 0) });
            };
            let mut truncated = 0;
            let mut dropped = 0;
            let mut calls = 0;
            // ... chunking, folding ...
            let record = diagnostics(calls, summary.chars().count(), tokens, truncated, dropped);
            Ok(StrategyOutcome::Completed { retain_from: cut.retain_from, replacement: vec![replacement], diagnostics: record })
        })
    }
}
